  return (
    <div className={cn("overflow-hidden whitespace-nowrap", className)} aria-label={text}>
      <motion.div aria-hidden className="flex w-max gap-10" style={{ x, skewX: reduced ? 0 : skew }}>
        {Array.from({ length: 4 }, (_, i) => <span key={i}>{text}</span>)}
      </motion.div>
